      "analysis": "İnsanları müjdelemek/uyarmak ve aralarındaki anlaşmazlıkları adaletle çözmek.",
      "solution": "1. İnsanları doğru davranışlara yönlendirip müjdelemek, yanlış inanç ve kötülüklere karşı uyarmak.\n2. İnsanların kendi başlarına çözemeyecekleri inanç ve adalet konularındaki anlaşmazlıkları vahyin rehberliğinde hak ve adaletle çözmek."
