      "solution": "• Metin Türü: Makale\n• Kanıt 1: Yazar kişisel duyguları yerine bilimsel araştırma sonuçlarına ve istatistiki sayısal verilere (%15 hata oranı) dayanmıştır.\n• Kanıt 2: Dil nesnel, ciddi ve öğreticidir; amaç okuyucuya bilgi aktarıp tezini kanıtlamaktır."
