      "Karekök Tanımı: Alanı bilinen bir karenin 1 kenar uzunluğunu bulma işlemidir. Sembolü √'tir (Örn: Alanı 64 cm² olan karenin bir kenarı √64 = 8 cm'dir).",
      "Karekök içi hiçbir zaman negatif olamaz: √-16 tanımsızdır."
