      "Öğrenim Gördüğü Okullar: Mahalle Mektebi (geleneksel), Şemsi Efendi Mektebi (çağdaş/modern), Selanik Mülkiye Rüştiyesi, Selanik Askerî Rüştiyesi (Kemal adını aldı), Manastır Askerî İdadisi, Harp Okulu (İstanbul), Harp Akademisi (Kurmay Yüzbaşı olarak mezun oldu)."
