      "Yabancı Düşünürler: Jean Jacques Rousseau (Milli Egemenlik), Montesquieu (Hukukun Üstünlüğü ve Güçler Ayrılığı), Voltaire (Akılcılık ve Bilim).",
      "Dömeke Meydan Savaşı (1897 Türk-Yunan Savaşı): Manastır Askerî İdadisi'ndeyken okuldan kaçıp savaşa katılmak istemesi onun yüksek vatanseverlik duygusunu gösterir."
