  "DKAB.8.1.1": {
    "outcomeCode": "DKAB.8.1.1",
    "topicTitle": "Kader ve Kaza İnancı",
    "quickNotes": [
      "Kader: Allah'ın her şeyi önceden bilmesi, bir ölçü, nizam ve plana göre takdir edip belirlemesidir (Planlama aşamasıdır).",
      "Kaza: Allah tarafından takdir edilen olayların zamanı ve yeri geldiğinde gerçekleşmesi, meydana gelmesidir (Gerçekleşme aşamasıdır).",
      "Örnek Ayrımı: \"Su 100°C'de kaynar\" veya \"Yer çekimi vardır\" kuralları KADER'dir. \"Isınan çaydanlıktaki suyun 100°C'ye ulaşıp kaynaması\" KAZA'dır."
    ],
    "examTraps": [
      "PÜF NOKTA: Cümlede kural, ölçü, kanun, takdir varsa KADER; olay yaşanmış, bitmiş, gerçekleşmiş ise KAZA'dır."
    ],
    "solvedExample": {
      "question": "Ayet Meali: 'Şüphesiz biz her şeyi bir ölçüye (kadere) göre yarattık.' (Kamer suresi, 49. ayet)\n\nKader ve kaza kavramlarını tanımlayarak, verilen ayetten hareketle evrendeki düzen ve kader inancı arasındaki ilişkiyi açıklayınız.",
      "analysis": "Kader: Allah'ın her şeyi önceden takdir etmesi ve planlaması. Kaza: Zamanı gelince yaratılması.",
      "solution": "• Kader: Yüce Allah'ın ezelden ebede kadar olacak her şeyi, tüm kanun ve ölçüleriyle önceden bilip planlaması ve takdir etmesidir.\n• Kaza: Allah tarafından takdir edilen bu olayların vakti ve şartları gelince gerçekleşmesi ve yaratılmasıdır.\n• Ayetle İlişkisi: Kamer suresindeki ayet, kâinatta hiçbir şeyin rastlantı ve başıboş olmadığını; gezegenlerin yörüngelerinden atomun yapısına kadar her şeyin kusursuz bir matematiksel denge ve ölçü (kader) ile var edildiğini gösterir."
    },
    "practiceQuestion": {
      "question": "8.1.1. Kader ve kaza inancını ayet ve hadislerle açıklar. konusunda benzer bir açık uçlu problemi kendi cümlelerinizle kurup çözünüz.",
      "hint": "Örnek sorudaki işlem basamaklarını ve model çözümü referans alınız."
    }
  },
