      "analysis": "Külli irade: Allah'ın sınırsız iradesi. Cüzi irade: İnsana verilen sınırlı seçme özgürlüğü. İnsan tercih hakkı olduğu için sorumludur.",
      "solution": "• Külli İrade: Yüce Allah'ın her şeyi kuşatan, sonsuz, sınırsız ve mutlak iradesidir. İnsanın anne-babası, ırkı, doğum yeri ve ölüm vakti gibi alanlar külli iradeye girer.\n• Cüzi İrade: Allah tarafından insana verilen, iki ya da daha fazla seçenek arasında serbestçe karar verebilen sınırlı iradedir.\n• Sorumluluk: İnsan iyiyi ve kötüyü akıl ve cüzi iradesiyle bizzat kendisi seçtiği için yaptıklarından dünyada ve ahirette sorumludur."
