      "Yanlış Kader Anlayışı (Fatalizm): \"Kaderim böyleymiş, ne yapsam boş\" diyerek tembellik yapmak, tedbir almamak İslam kader inancıyla bağdaşmaz. İnsan irade ve akıl sahibi olup eylemlerinden sorumludur."
